assert all(sha(root/f)==h for f,h in source.items())
write(out/'candidate-identity.json',{'candidate':candidate,'observed_main':candidate,'main_checked_at':datetime.now(UTC).isoformat(),'ci_run':36472142614,'candidate_tree':tree(candidate),'prior_tested_commit':'62948bab49896bd0687686e0170b6d193dbdc52f','prior_tree':tree('62948bab49896bd0687686e0170b6d193dbdc52f'),'trees_identical':tree(candidate)==tree('62948bab49896bd0687686e0170b6d193dbdc52f'),'local_inspected_modules_match_candidate':source,'prior_evidence_policy':'Historical evidence remains labeled with its original commit; identical trees justify reuse only for source-dependent checks, not environment/runtime freshness.'})
review=root/'docs/release-evidence/report-review-20260928';approved=json.loads((review/'owner-content-approval.json').read_text());meta=json.loads((review/'approved-bundle.json').read_text()); bundlepath=root/meta['path'];assert sha(bundlepath)==meta['sha256'];assert sha(review/'review.json')==approved['review_file_sha256']; bundle=json.loads(gzip.decompress(bundlepath.read_bytes()));baseline=json.loads((root/'release-artifacts/2025-26/release-corrected-unreviewed.json').read_text());oldreview=json.loads((review/'review.json').read_text())
labelsdir=root/'docs/release-evidence/evaluation-label-review-20260907';labelsfile=labelsdir/'labels.jsonl';labelreview=json.loads((labelsdir/'review.json').read_text());labels=[json.loads(s) for s in labelsfile.read_text().splitlines()];assert sha(labelsfile)==labelreview['labels_file_sha256'];assert len(labels)==120
canon={k:bundle['data'][k] for k in baseline['data'] if k!='reports'};assert digest(canon)==labelreview['identity']['canonical_data_sha256'];assert canon=={k:v for k,v in baseline['data'].items() if k!='reports'}
c=Canonical(bundle);lookup={}
for col in ['games','player_game_stats','team_game_stats','period_scores']:
 for r in bundle['data'][col]:
  entry=c.evidence([r],col)[0];lookup[(col,entry['canonical_id'])]=entry['row_sha256']
