assert oldreview['replacement_audit']['summary']['passed']==101 and oldreview['replacement_audit']['summary']['unresolved']==0
refs=[s for l in labels for s in l['canonical_sources']];assert all(lookup[(s['collection'],s['canonical_id'])]==s['row_sha256'] for s in refs)
