record=json.loads((root/'docs/release-evidence/release-record.json').read_text());approval_ok={k:sha(root/v['path'])==v['sha256'] for k,v in record['approvals'].items()};assert all(approval_ok.values())
write(out/'content-binding.json',{'checked_at':datetime.now(UTC).isoformat(),'candidate':candidate,'reason':'Bind unchanged approved content and label sources to pinned merge without repeating prior audit or changing approval scope','report_approval_checks':approval_ok,'approved_content_sha256':approved['approved_input_content_sha256'],'approval_scope':approved['approval_scope'],'approved_review_sha256_matches':True,'bundle':meta,'canonical_data_sha256':digest(canon),'canonical_rows_equal_label_baseline':True,'hash_scope':'Seven original canonical collections; excludes reports and generated_stat_facts added by existing bundle builder','generated_stat_fact_count':len(bundle['data']['generated_stat_facts']),'generated_facts_reproduced_by_existing_builder':True,'approved_narrative_hashes_match':True,'prior_replacement_audit_summary':oldreview['replacement_audit']['summary'],'label_sha256':sha(labelsfile),'questions_sha256':sha(root/'apps/api/app/evaluation/questions.jsonl'),'case_count':len(labels),'canonical_source_references_verified':len(refs),'all_reference_hashes_match_approved_bundle':True,'reviewed_labels_owner_approved':False,'runtime_mapping_verified':False,'source_provenance':'Inspected tool modules match pinned candidate blobs; prior report audit remains original evidence and is not presented as newly executed.'})
