print(json.dumps({'candidate_tree_matches_prior':tree(candidate)==tree('62948bab49896bd0687686e0170b6d193dbdc52f'),'canonical_refs_verified':len(refs),'approval_checks':approval_ok,'package_sha256':sha(out/'evaluation-approval-package.json')},indent=2))
